-- =============================================================================
-- VICS — 관전봇 매치업 생성 주제 풀
-- 운영 카테고리 6종: 영원한 난제 / 패션 / 맛집 / 맛식 / 라이프 스타일 / 연애
-- supabase_virtual_bot_matchups.sql 이후 실행하세요.
--
-- 카테고리 기획
--   맛집: 특정 장소·식당·지역 특성·분위기·서비스 비교. 맛집 탐방 경험을 올리게.
--   맛식: 음식 자체(맛·식감·조합) + 건강식·식단. 집이 아니라 메뉴.
--   영원한 난제: 일상 난제. 연애(썸·사귐·이별·데이트)는 연애 카테고리로만.
--                정치·종교·젠더 이슈 금지. (테토에겐 등 젠더 라벨도 넣지 않음)
--   패션: 옷·핏·소비 (기존 유지)
--   라이프 스타일: 일상 취향·상황·선택·트렌드. 음식 맛·옷·매장 탐방·연애 난제는 넣지 않음.
--   연애: 두 사람 사이의 호감·사랑·썸·사귐·이별 고민. 생활 습관·음식·패션은 넣지 않음.
--
-- 전제: 오른쪽 도전자가 무엇을 올릴지 모름.
--   제목 ≤60자 / 설명 ≤200자 / 본문 = A측 한 방
-- image_prompt = 한국 20대 초중반 사람 포함 가능. 유명인·글자·로고 없음.
-- =============================================================================

ALTER TABLE public.virtual_bot_matchup_prompts
  ADD COLUMN IF NOT EXISTS image_prompt text;

TRUNCATE public.virtual_bot_matchup_prompts RESTART IDENTITY;

INSERT INTO public.virtual_bot_matchup_prompts
  (category_id, title, description, body_text, tags, image_prompt)
VALUES
  -- ───────── 영원한 난제: 일상 난제 (연애 제외) ─────────
  ('eternal_quest', '인스타 보면 나만 뒤처진 기분, 이게 정상임?', '난 스토리 보다가 현타 오면 바로 끄는 쪽이 멘탈 지킴. 비교하면서 하루 버리는 거 ㄹㅇ 손해. 아직 들여다보는 사람 나와봐.', '인스타는 하이라이트만 올림. 내 평일이랑 비교하는 순간 멘탈 나감. 끄는 게 이득임.', ARRAY['인스타','현타','라이프'], 'A Korean woman in her early 20s in bed at night putting her phone face down, tired natural expression'),
  ('eternal_quest', '갓생 실패했는데, 루틴 포기하는 게 맞음?', '난 3일 만에 무너져도 다시 켜는 쪽이 이김. 완벽한 갓생 집착이 번아웃임. 한 방에 끝내려는 사람 반박해봐.', '갓생은 연속보다 재시작 횟수임. 오늘 망해도 내일 알람만 다시 켜면 됨.', ARRAY['갓생','번아웃','루틴'], 'A Korean man in his early 20s waking up messy-haired to an alarm, planner on the nightstand, morning light'),
  ('eternal_quest', '본가 사는 거, 20대에 꿀임 아님 현타임?', '난 월세 아끼는 본가가 지금 제일 이득이라고 봄. 자취 자랑이 통장보다 우선이면 나중에 선택지가 없음. 독립 자랑파 나와봐.', '본가는 꿀잠이지 못 나온 게 아님. 월세 나가면 친구 만나는 횟수부터 줄어듦.', ARRAY['본가','월세','라이프'], 'A Korean woman in her early 20s eating breakfast at a family home table in pajamas, cozy and unbothered'),
  ('eternal_quest', '숏폼 하루 두 시간, 이 정도면 과함?', '난 릴스 끄고 잠드는 쪽이 다음 날 이김. 자기 전에 한 시간 더 보는 거 ㄹㅇ 수면 도둑임. 아직 무한스크롤파 들어와.', '숏폼은 쉬는 게 아니라 시간 임대임. 꺼두는 게 갓생보다 먼저임.', ARRAY['숏폼','수면','라이프'], 'A Korean man in his early 20s putting his phone on the nightstand and turning toward a book, sleepy but resolute'),
  ('eternal_quest', '20대에 적금부터 넣는 거, 이득임?', '난 적금 먼저 넣고 남는 돈으로 노는 게 맞음. 집 나갈 때 현금 없으면 선택지가 사라짐. 지금 다 쓰는 논리 들어봄.', '적금 안 넣으면 나중에 월세 앞에서 손 비게 됨. 노는 돈은 넣고 남은 걸로.', ARRAY['적금','자취','돈'], 'A Korean woman in her early 20s at a desk checking a bank app, modest coffee, relieved expression'),
  ('eternal_quest', '카톡 읽씹, 이 정도면 매너 아님?', '난 읽씹하면 관계 온도 내려가는 거 맞다고 봄. 바쁜 척해도 한 줄은 됨. 반박할 사람?', '읽씹은 거절보다 더 별로임. 한 줄이라도 남기는 게 매너 최저선임.', ARRAY['카톡','읽씹','관계'], 'A Korean man in his early 20s at a cafe staring at a phone with a conflicted face, iced coffee on the table'),

  -- ───────── 패션 ─────────
  ('fashion', '미니멀 옷장, 이게 이득임?', '난 색깔 줄인 옷장이 아침 결정장애를 없앤다고 봄. 유행 다 사면 코디가 숙제됨. 맥시멀파 나와봐.', '미니멀은 재미없다는 게 아님. 입는 횟수가 많은 옷이 진짜 내 스타일임.', ARRAY['미니멀','옷장','코디'], 'A Korean woman in her early 20s choosing a beige outfit from a small minimal closet, morning apartment, candid'),
  ('fashion', '중고로 옷 사는 거, 별로임?', '난 중고가 가격이랑 환경 둘 다 이득이라고 봄. 새상표만 고집하면 20대 예산이 무너짐. 새거만파 논리 가져와.', '중고는 촌내가 아니라 센스임. 한 철 입고 버리는 게 더 티 남.', ARRAY['중고','패션','가성비'], 'A Korean man in his early 20s trying on a secondhand jacket in a small room, looking at a mirror, natural face'),
  ('fashion', '오운완 룩, 밖에 입고 다녀도 됨?', '난 운동 동선이면 오운완 룩이 제일 정직하다고 봄. 꾸안꾸 강요하는 눈치 극혐. 꾸밈파 들어와.', '오운완은 인증용이 아니라 움직임 최적화임. 짐에서 옷 갈아입는 시간이 아깝다.', ARRAY['오운완','운동','룩'], 'A Korean woman in her early 20s walking on a Seoul sidewalk in oversized hoodie and sneakers, gym bag, candid street photo'),
  ('fashion', '명품 하나, 지금 사도 됨?', '난 무지출 한 달 하고 사는 게 충동 방어라고 봄. 지금 아니면 못 산다는 논리 ㄹㅇ 마케팅임. 지금 사자파 나와봐.', '명품은 목표가 될 순 있음. 할부로 자존감 사는 건 다음 달 현타임.', ARRAY['명품','소비','충동'], 'A Korean man in his early 20s holding an unbranded structured bag, thinking, store window behind him, no logos'),
  ('fashion', '검정만 입는 거, 센스임 귀차임?', '난 검정이 실패 확률 낮은 유니폼이라고 봄. 컬러 강요는 취향 간섭임. 컬러파 반박해봐.', '검정은 무난함이 아니라 선택 비용 절감임. 포인트는 가방이랑 신발로 주면 됨.', ARRAY['검정','미니멀','코디'], 'A Korean woman in her early 20s in an all-black casual outfit on a city street, confident natural pose'),
  ('fashion', '운동화가 진리임, 구두가 진리임?', '난 운동화가 출퇴근·약속 전부 커버해서 이득이라고 봄. 구두 하루면 저녁에 발부터 항복임. 구두파 나와봐.', '편해야 표정이 남음. 예쁜 신발에 절뚝이면 코디가 다 죽음.', ARRAY['운동화','구두','편함'], 'A Korean man in his early 20s commuting in clean sneakers, relaxed walk, Seoul sidewalk'),
  ('fashion', '계절 옷 미리 사기, 이득임?', '난 시즌 끝나기 전에 사는 게 가격 이득이라고 봄. 필요할 때 사면 이미 품절임. 즉흥구매파 논리 들어봄.', '미리 사는 건 과소비가 아니라 일정 관리임. 갑자기 추워지면 패딩값이 두 배임.', ARRAY['시즌','쇼핑','계획'], 'A Korean woman in her early 20s holding a light jacket and a padded coat, closet behind her, deciding'),
  ('fashion', '모자·마스크, 요즘 패션임 방어임?', '난 얼굴이 안 나온 날은 모자부터가 코디라고 봄. 꾸민 척 안 해도 되는 방어막임. 맨얼굴 필수파 들어와.', '모자는 대충이 아니라 컨디션 조절임. 20대도 매일 화보일 필요 없음.', ARRAY['모자','컨디션','패션'], 'A Korean man in his early 20s leaving home in a cap and jacket, tired but styled, apartment hallway'),
  ('fashion', '브랜드보다 핏, 이게 맞음?', '난 로고보다 어깨 핏이 사람이 보인다고 봄. 브랜드 자랑은 가까운 사람만 앎. 로고파 나와봐.', '핏이 맞으면 저렴해도 비싸 보임. 브랜드만 믿으면 사이즈에서 들킴.', ARRAY['핏','브랜드','코디'], 'A Korean woman in her early 20s wearing a well-fitted jacket, window light on her shoulder line, no logos'),
  ('fashion', '옷 렌탈, 지금 세대에 이득임?', '난 한 철 행사용은 렌탈이 옷장 포화 안 만드는 길이라고 봄. 내 거라야 애착 생긴다는 쪽 반박해봐.', '렌탈은 유행 따라가다 옷장 터지는 거 방지임. 자주 입는 기본템만 사면 됨.', ARRAY['렌탈','패션','가성비'], 'A Korean woman in her early 20s unzipping a garment bag with a formal outfit, small closet of basics behind her'),

  -- ───────── 맛집: 장소·지역·분위기·서비스·탐방 ─────────
  ('맛집', '성수 카페 거리, 분위기 탐방 진리임?', '난 성수 창가 자리에 앉는 게 그 주 탐방 하이라이트라고 봄. 핫해서 싫은 건 별개. 다른 동네 분위기파 나와봐.', '성수는 음료보다 골목 온도임. 탐방은 그 거리 걷는 시간이 남음.', ARRAY['성수','카페','탐방'], 'A Korean woman in her early 20s walking a brick-cafe street in Seongsu, looking at shopfronts, candid'),
  ('맛집', '망원·연남 골목, 핫플보다 탐방 이득임?', '난 망원 골목 간판 따라가는 게 웨이팅 전쟁보다 탐방 가성비라고 봄. 핫플 인증샷파 논리 가져와.', '골목은 줄이 자산이 아님. 빈자리 보고 들어가는 게 탐방 실력임.', ARRAY['망원','연남','골목'], 'A Korean man in his early 20s turning into a quiet Mangwon alley toward a small restaurant sign'),
  ('맛집', '지방 맛집 탐방, 서울 핫플보다 낫음?', '난 기차 타고 간 지방 집이 서울 오픈런보다 기억이 남는다고 봄. 서울만 탐방이라는 사람 반박해봐.', '지방 집은 서비스가 덜 바쁨. 그 동네 공기까지 메뉴임.', ARRAY['지방','탐방','지역'], 'A Korean woman in her early 20s getting off a regional train with a small bag, small-town station, excited'),
  ('맛집', '시장 골목 탐방이 대로변보다 맞음?', '난 시장 안쪽 손님이 현지인인 집이 탐방 정답이라고 봄. 대로변 포토존파 들어와.', '시장은 분위기랑 회전이 보임. 대로변은 간판이 먼저 보임.', ARRAY['시장','골목','탐방'], 'A Korean man in his early 20s walking through a Korean traditional market aisle, looking at stall fronts'),
  ('맛집', '웨이팅 긴 집, 서비스까지 보면 가치 있음?', '난 한 시간 기다렸는데 직원 응대가 별로면 그 집은 탐방 실패라고 봄. 맛만 보면 된다는 쪽 나와봐.', '웨이팅은 기대값임. 자리 안내가 차면 그 집 급이 보임.', ARRAY['웨이팅','서비스','맛집'], 'A Korean woman in her early 20s being seated by staff after waiting, Korean restaurant interior, relieved smile'),
  ('맛집', '창가 2층 자리가 그 집 분위기임?', '난 창가 아니면 그 집 탐방이 반만 됐다고 봄. 안쪽 자리도 상관없다는 사람 논리 들어봄.', '창가는 인스타용이 아니라 그 집 공기임. 자리 못 맡으면 다른 날 감.', ARRAY['창가','분위기','자리'], 'A Korean man in his early 20s sitting at a second-floor window cafe seat, city view, relaxed'),
  ('맛집', '직원 친절이 재방문 이유 맞음?', '난 음식 비슷하면 응대 좋은 집으로 다시 감. 불친절해도 맛이면 된다는 쪽 반박해봐.', '서비스는 덤이 아님. 탐방에서 기분 상하면 그 골목 전체가 식음.', ARRAY['서비스','친절','재방문'], 'A Korean woman in her early 20s smiling as a server sets down water, warm casual restaurant'),
  ('맛집', '혼밥 자리 있는 집이 탐방 실력임?', '난 1인석·바 좌석 있는 집이 혼자 탐방 가능 지역이라고 봄. 둘이 오라는 눈치 집 극혐. 다른 기준 있어?', '혼밥석은 용기 문제가 아니라 가게 설계임. 그 동네를 일주일에 한 번 더 가게 됨.', ARRAY['혼밥','1인석','탐방'], 'A Korean man in his early 20s sitting at a single counter seat in a small restaurant, calm, chopsticks ready'),
  ('맛집', '24시 식당이 올빼미 탐방 인프라임?', '난 새벽에 문 연 집이 그 지역 생존 맛집이라고 봄. 일찍 닫는 감성집만 탐방이라는 사람 나와봐.', '24시는 낭만이 아니라 퇴근 루트임. 닫힌 골목은 탐방 동선이 끊김.', ARRAY['심야','24시','탐방'], 'A Korean woman in her early 20s sitting at a neon diner counter late at night, tired but comfortable'),
  ('맛집', '매장 앉는 집이 포장창구보다 탐방임?', '난 테이블에 앉아야 그 집 온도가 남는다고 봄. 포장만 빠른 집도 인정하는데, 탐방은 자리값임. 포장파 논리 가져와.', '매장은 공간 서비스까지 먹는 거임. 창구만 있으면 그 집은 배달이랑 비슷해짐.', ARRAY['매장','분위기','탐방'], 'A Korean man in his early 20s sitting down inside a restaurant, takeout window visible near the door'),
  ('맛집', '고깃집 불판 서비스가 그 집 급임?', '난 불판 갈아주고 속도 맞춰주는 집이 회식 탐방 1순위라고 봄. 고기만 두꺼우면 된다는 쪽 들어와.', '고깃집은 불이 서비스임. 직원 동선이 그 집 지역 급을 보여줌.', ARRAY['고깃집','서비스','회식'], 'Young Korean people in their early 20s at a barbecue table as staff changes the grill, lively'),
  ('맛집', '카페는 창가 뷰가 콘센트보다 그 집임?', '난 창가 뷰가 그 카페를 고른 이유라고 봄. 콘센트 전쟁이 탐방의 전부는 아님. 카공 생존파 나와봐.', '카페 탐방은 그 자리의 빛임. 충전기만 보면 어느 집이든 같아짐.', ARRAY['카페','창가','분위기'], 'A Korean woman in her early 20s at a sunlit cafe window, laptop closed, looking outside, iced drink'),

  -- ───────── 맛식: 음식 맛·식감·조합 ─────────
  ('맛식', '찍먹이 진리임, 이게 맞음?', '난 찍먹이 소스 컨트롤이라고 봄. 부먹으면 마지막이 흐물해짐. 부먹파 논리 가져와.', '찍먹은 취향 아니고 식감 관리임. 부먹 하면 중간부터 다른 음식 됨.', ARRAY['찍먹','식감','맛'], 'A Korean man in his early 20s dipping crispy fried food into sauce, close candid'),
  ('맛식', '매운맛이 스트레스 해소 맛임?', '난 매운 게 한 끼를 리셋한다고 봄. 순한 맛만 고르라는 잔소리 극혐. 순한맛파 들어와.', '매운맛은 성격이 아니라 맛의 볼륨임. 단짠만 찾다 보면 입이 심심해짐.', ARRAY['매운맛','떡볶이','맛'], 'A Korean woman in her early 20s eating spicy tteokbokki, flushed happy face, steam rising'),
  ('맛식', '단짠 조합, 아직도 최고 맛임?', '난 단짠이 한 입에 끝나는 설계라고 봄. 건강식만 고집하면 다음 끼가 폭식임. 클린식파 논리 들어봄.', '단짠은 죄책감용 단어가 아님. 한 끼 만족이 야식 한 끼를 줄임.', ARRAY['단짠','맛','조합'], 'A Korean man in his early 20s enjoying fried chicken and a sweet drink, satisfied expression'),
  ('맛식', '국물이 진해야 그 집이 아니라 그 맛이임?', '난 국밥·라면은 국물 농도가 맛의 전부라고 봄. 건더기파 나와봐.', '국물은 간이 아니라 여운임. 싱거우면 한 술이 안 넘어감.', ARRAY['국물','국밥','맛'], 'A Korean woman in her early 20s lifting a spoon of steaming rich Korean soup, close food moment'),
  ('맛식', '겉바속촉이 치킨 진리 맛임?', '난 바삭 한 번이면 그 다음 입은 육즙이라고 봄. 양념 범벅파 논리 가져와.', '치킨은 소리랑 촉감이 맛임. 눅으면 양념이 덮어도 티 남.', ARRAY['치킨','겉바속촉','식감'], 'A Korean man in his early 20s breaking crispy fried chicken, juicy inside visible, casual table'),
  ('맛식', '치즈 늘어나는 게 맛임?', '난 늘어나는 순간이 그 메뉴의 하이라이트라고 봄. 치즈 없는 깔끔파 반박해봐.', '치즈는 간판 토핑이 아니라 식감임. 안 늘어나면 그 메뉴가 아님.', ARRAY['치즈','식감','맛'], 'A Korean woman in her early 20s pulling stretchy cheese from a hot dish, delighted face'),
  ('맛식', '면발 탱탱한 게 맛임?', '난 면이 무르면 소스가 뭔지 상관없다고 봄. 소스 맛만 보자는 쪽 들어와.', '면발은 씹는 맛의 뼈대임. 퍼지면 국물만 남은 거임.', ARRAY['면발','면','식감'], 'A Korean man in his early 20s lifting bouncy noodles with chopsticks, steam, close-up'),
  ('맛식', '뜨거울 때가 맛임, 식어야 맛임?', '난 김 오를 때가 그 음식 피크라고 봄. 식혀 먹는 미식파 논리 들어봄.', '온도가 간임. 식으면 기름이 먼저 느껴짐.', ARRAY['온도','맛','식감'], 'A Korean woman in her early 20s blowing on a hot spoonful, eager expression, home table'),
  ('맛식', '양념이 진리임, 본연의 맛이 진리임?', '난 양념이 한 입을 기억에 남긴다고 봄. 재료 맛만 보자는 쪽 나와봐.', '양념은 과장이 아니라 여운임. 담백만 찾다 보면 다음 끼가 생각남.', ARRAY['양념','본연','맛'], 'A Korean man in his early 20s tasting a well-seasoned Korean side dish, nodding, casual meal'),
  ('맛식', '빙수가 여름 디저트 진리 맛임?', '난 얼음 식감이 아이스크림보다 오래간다고 봄. 아이스크림파 반박해봐.', '빙수는 온도랑 고명이 맛임. 녹기 전에 승부가 남.', ARRAY['빙수','디저트','여름'], 'A Korean woman in her early 20s eating Korean shaved ice with toppings, summer cafe, bright smile'),
  ('맛식', '김밥은 속이 맛임, 밥이 맛임?', '난 속 재료 한 줄이 김밥 전체를 결정한다고 봄. 밥 간만 잘하면 된다는 쪽 들어와.', '김밥은 한 입의 구성임. 속이 싱거우면 김이 아무리 고소해도 빈맛임.', ARRAY['김밥','속','맛'], 'A Korean man in his early 20s biting into kimbap, filling visible, convenience-store or home table'),
  ('맛식', '민트초코, 맛있음 아님?', '난 민트 향이 단맛을 리셋해서 더 먹는다고 봄. 치약 맛이라는 사람 나와봐.', '민초는 취향 테러가 아니라 조합임. 초코만 있으면 중간에 질림.', ARRAY['민초','디저트','맛'], 'A Korean woman in her early 20s eating mint chocolate ice cream, playful expression, cafe dessert'),

  -- ───────── 맛식: 건강식·식단 ─────────
  ('맛식', '단백질 매끼, 이게 맛있는 한 끼임?', '난 매끼 단백질 넣는 게 다음 끼 폭식을 막는 맛이라고 봄. 탄수 위주가 더 배부르다는 쪽 나와봐.', '단백질은 식단 숙제가 아니라 한 입의 밀도임. 없으면 한 시간 뒤에 또 배고픔.', ARRAY['단백질','식단','맛'], 'A Korean man in his early 20s eating grilled chicken and eggs at a small table, satisfied not posed'),
  ('맛식', '저속노화 식단, 맛도 있음?', '난 기름·당 줄인 한 끼가 입이 덜 피곤해서 더 오래 먹는다고 봄. 자극 맛만 진리라는 사람 반박해봐.', '저속노화는 심심함이 아니라 여운임. 매 끼 자극이면 혀가 먼저 지침.', ARRAY['저속노화','식단','맛'], 'A Korean woman in her early 20s eating a colorful vegetable bowl, natural smile, home kitchen light'),
  ('맛식', '샐러드 점심, 한식보다 맛임?', '난 바삭 채소랑 소스가 점심 속도를 이긴다고 봄. 국밥 한 그릇이 진리라는 쪽 들어와.', '샐러드는 다이어트용이 아니라 식감 조합임. 소스만 맞으면 한식이랑 다른 만족임.', ARRAY['샐러드','점심','건강식'], 'A Korean woman in her early 20s eating a loaded salad at a cafe, crunchy vegetables, candid'),
  ('맛식', '닭가슴살, 간만 맞으면 맛임?', '난 염지·에어프라이면 닭가슴살이 치킨 대체 식감이라고 봄. 퍽퍽해서 못 먹겠다는 사람 논리 가져와.', '닭가슴살은 재료가 아니라 간의 문제임. 건조하면 식단이 형벌이 됨.', ARRAY['닭가슴살','식단','식감'], 'A Korean man in his early 20s slicing seasoned grilled chicken breast, juicy inside, meal prep containers'),
  ('맛식', '제로슈거가 단맛 대체 됨?', '난 제로가 후식 참는 것보다 혀를 달래준다고 봄. 인공단맛 극혐파 나와봐.', '제로는 속임수가 아니라 단맛 볼륨 조절임. 당 폭주 한 잔이 다음 끼를 망침.', ARRAY['제로','단맛','식단'], 'A Korean woman in her early 20s drinking a zero-sugar soda with a meal, relaxed cafe table'),
  ('맛식', '현미밥이 흰쌀보다 맛임?', '난 현미 식감이 한 술을 더 오래 가게 한다고 봄. 흰쌀 부드러운 맛이 진리라는 쪽 반박해봐.', '현미는 건강 핑계가 아니라 씹는 맛임. 흰쌀만 있으면 반찬이 과해짐.', ARRAY['현미','밥','건강식'], 'A Korean man in his early 20s eating a bowl of brown rice with Korean side dishes, home table'),
  ('맛식', '요거트볼이 아침 진리 맛임?', '난 새콤이랑 견과 식감이 아침에 제일 빨리 입이 깬다고 봄. 김밥·빵 아침파 들어와.', '요거트볼은 간식이 아니라 첫 끼 조합임. 달기만 하면 그건 디저트임.', ARRAY['요거트','아침','건강식'], 'A Korean woman in her early 20s eating a yogurt bowl with fruit and granola, morning window light'),
  ('맛식', '간헐적 단식 한 끼, 더 맛있어짐?', '난 공복 뒤에 먹는 한 끼가 간도 식감도 더 선명하다고 봄. 세 끼 꼬박이 맛의 기본이라는 사람 나와봐.', '단식은 금식이 아니라 한 끼 밀도임. 배고플 때 먹으면 간이 과해지지 않음.', ARRAY['단식','한끼','식단'], 'A Korean man in his early 20s sitting down to a late hearty first meal of the day, focused and hungry'),

  -- ───────── 영원한 난제 추가 ─────────
  ('eternal_quest', '주말 약속 두 개, 과함임?', '난 주말 하나 비워두는 게 멘탈 충전이라고 봄. 빽빽한 스케줄이 인싸라는 사람 나와봐.', '주말은 실적이 아님. 공백이 있어야 다음 주도 사람이 됨.', ARRAY['주말','약속','라이프'], 'A Korean woman in her early 20s cancelling one weekend plan and staying home in loungewear, relieved'),
  ('eternal_quest', '배달 기본값, 요리하는 게 이득임?', '난 배달 한 번 참으면 주말 예산이 생긴다고 봄. 바쁜데 왜 하냐고 하는 사람 반박해봐.', '배달은 편의지 기본값이 아님. 한 끼 해먹으면 통장이 숨 쉼.', ARRAY['배달','요리','돈'], 'A Korean man in his early 20s cooking a simple pan meal in a small kitchen, phone with a delivery app face down'),
  ('eternal_quest', '친구 소수 정예, 이게 행복임?', '난 소수 정예가 유지 비용 적어서 이득이라고 봄. 넓은 관계는 단톡에 체력 다 씀. 인싸파 논리 들어봄.', '친구 수는 프로필이 아님. 바쁠 때 한 명 나오는 게 진짜임.', ARRAY['친구','소수정예','관계'], 'Two Korean friends in their early 20s talking at a quiet cafe table, unhurried, candid'),
  ('eternal_quest', '알람 다섯 개, 이게 생존임?', '난 알람 여러 개가 스누즈 습관을 더 만든다고 봄. 한 방에 일어나는 쪽이 아침을 이김. 알람 도미노파 들어와.', '알람 다섯 개는 보험이 아니라 수면 도둑임. 첫 알람에 일어나는 게 갓생임.', ARRAY['알람','수면','루틴'], 'A Korean woman in her early 20s turning off a single morning alarm and sitting up, messy hair, daylight'),
  ('eternal_quest', '회식, 빠지는 게 맞음?', '난 약속 있는 회식은 빠져도 된다고 봄. 맨날 참석이 성실이라는 사람 나와봐.', '회식은 업무가 아님. 억지로 남으면 다음 날 몸이 먼저 짐.', ARRAY['회식','직장','눈치'], 'A Korean man in his early 20s leaving an office at dusk with a bag, coworkers still heading to dinner behind him'),
  ('eternal_quest', '연차, 눈치 보고 쓰는 게 맞음?', '난 미리 말하고 쓰는 연차가 매너라고 봄. 팀 바쁠 때 쉬면 민폐라는 쪽 반박해봐.', '연차는 혜택이지 결석이 아님. 눈치로 쌓아 두면 쉬지도 못함.', ARRAY['연차','직장','휴식'], 'A Korean woman in her early 20s submitting a day-off request on a laptop, calm office morning'),
  ('eternal_quest', '친구에게 돈 빌려주는 거, 이득임?', '난 금액이 커지면 관계보다 기록이 먼저라고 봄. 친구인데 뭘 적냐는 사람 들어와.', '빌림은 우정이 아니라 약속임. 날짜 없는 돈은 관계가 먼저 상함.', ARRAY['돈','친구','빌림'], 'A Korean man in his early 20s hesitating before sending money on a phone, friend across a cafe table'),
  ('eternal_quest', '축의금, 이 금액이 맞음?', '난 내 형편 기준으로 내는 게 예의라고 봄. 받은 만큼 돌려줘야 한다는 쪽 논리 가져와.', '축의금은 체면 경쟁이 아님. 부담되면 참석보다 마음이 먼저 상함.', ARRAY['축의금','경조사','돈'], 'A Korean woman in her early 20s putting an envelope into a small bag before a wedding, thoughtful'),
  ('eternal_quest', '층간소음, 말을 꺼내는 게 맞음?', '난 참다 폭발하는 것보다 한 번 말하는 게 낫다고 봄. 그냥 참는 게 어른이라는 사람 나와봐.', '한 번은 요청이지 싸움이 아님. 쪽지만 붙이면 감정만 쌓임.', ARRAY['층간소음','자취','이웃'], 'A Korean man in his early 20s looking up at the ceiling of a small apartment, earplugs on the desk'),
  ('eternal_quest', '단체 카톡 답장, 의무임?', '난 호명된 말만 답해도 된다고 봄. 단톡마다 리액션이 매너라는 쪽 반박해봐.', '단톡은 회의가 아님. 모든 말에 답하면 하루가 알림으로 감.', ARRAY['단톡','답장','매너'], 'A Korean woman in her early 20s muting a group chat and replying to one message, commute seat'),
  ('eternal_quest', '10분 지각, 이 정도면 매너임?', '난 10분도 상대 시간을 빌리는 거라고 봄. 서울에선 기본이라는 사람 들어와.', '지각은 사정이 아니라 약속 수정임. 미리 한 줄이 10분을 커버함.', ARRAY['지각','약속','매너'], 'A Korean man in his early 20s hurrying toward a cafe, checking the time, apologetic face'),
  ('eternal_quest', '부모님께 월급 공개, 해야 함?', '난 큰 결정만 공유하는 게 독립이라고 봄. 숨기면 불효라는 쪽 논리 들어봄.', '월급 공개는 효도가 아니라 간섭의 시작일 수 있음. 용돈 약속은 따로임.', ARRAY['월급','부모','독립'], 'A Korean woman in her early 20s closing a banking app before a family dinner, calm not secretive'),
  ('eternal_quest', '첫 이직, 언제가 맞음?', '난 배운 게 문장으로 되면 움직인다고 봄. 1년은 채워야 예의라는 사람 나와봐.', '이직은 배신이 아님. 버티기만 하는 1년은 경력이 아니라 시간임.', ARRAY['이직','직장','타이밍'], 'A Korean man in his early 20s updating a resume at a desk after work, city window, focused'),
  ('eternal_quest', '술자리 2차, 빠지면 김새임?', '난 1차에서 인사하고 가는 게 충분하다고 봄. 2차까지 가야 친해진다는 쪽 반박해봐.', '2차는 친목 시험이 아님. 몸 상태를 말하는 게 매너임.', ARRAY['술자리','2차','거절'], 'A Korean woman in her early 20s waving goodbye outside a restaurant while others head to a second bar'),

  -- ───────── 패션 추가 ─────────
  ('fashion', '흰티가 옷장 진리임?', '난 흰티가 실패 확률 낮은 기본값이라고 봄. 패턴 티가 개성이라는 쪽 나와봐.', '흰티는 무난함이 아니라 코디 플랫폼임. 포인트는 겉옷이랑 신발이 하면 됨.', ARRAY['흰티','기본템','코디'], 'A Korean man in his early 20s wearing a plain white tee and a jacket, Seoul street, candid no logos'),
  ('fashion', '가방은 하나면 됨?', '난 매일 드는 가방 하나가 코디를 이긴다고 봄. 유행 백 돌리는 거 예산 붕괴임. 백 컬렉션파 반박해봐.', '가방은 개수가 아니라 동선임. 매일 안 들면 그건 짐임.', ARRAY['가방','미니멀','패션'], 'A Korean woman in her early 20s carrying one well-worn structured bag on the subway, natural'),
  ('fashion', '안경이 패션임, 보정임?', '난 안경이 얼굴 라인보다 코디 완성도가 높다고 봄. 렌즈만 진리라는 사람 들어와.', '안경은 숨김이 아니라 얼굴 프레임임. 잘 고르면 화장보다 빨리 정돈됨.', ARRAY['안경','패션','얼굴'], 'A Korean man in his early 20s adjusting simple glasses in a hallway mirror, casual outfit'),
  ('fashion', '여름 샌들, 밖에 신고 다녀도 됨?', '난 더우면 샌들이 표정을 살린다고 봄. 운동화 고집하다 발 붓는 거 손해. 발등 가림파 나와봐.', '편해야 걸음이 예쁨. 예쁜 신발에 절뚝이면 코디가 죽음.', ARRAY['샌들','여름','편함'], 'A Korean woman in her early 20s walking a sunny Seoul sidewalk in simple sandals, relaxed pace'),
  ('fashion', '레이어드, 과함임 센스임?', '난 얇게 겹치는 게 체온이랑 실루엣 둘 다 잡는 길이라고 봄. 한 장만 입는 게 깔끔이라는 쪽 논리 가져와.', '레이어드는 과장이 아니라 온도 조절임. 실내면 겉옷만 벗으면 됨.', ARRAY['레이어드','코디','계절'], 'A Korean man in his early 20s wearing a tee, shirt, and light jacket, indoor-outdoor cafe doorway'),
  ('fashion', '빈티지 마켓, 중고보다 탐방임?', '난 마켓에서 고르는 시간이 코디 실력이라고 봄. 새상표 온라인이 빠르다는 사람 반박해봐.', '빈티지는 촌내가 아니라 한 벌의 이야기임. 빨리 사는 옷은 빨리 질림.', ARRAY['빈티지','마켓','패션'], 'A Korean woman in her early 20s browsing a vintage clothing rail outdoors, holding up a jacket'),
  ('fashion', '액세서리 최소, 이게 세련임?', '난 포인트 하나만 주는 게 실패가 적다고 봄. 겹칠수록 개성이라는 쪽 들어와.', '액세서리는 개수가 센스가 아님. 얼굴이 가려지면 코디가 짐이 됨.', ARRAY['액세서리','미니멀','센스'], 'A Korean woman in her early 20s wearing one simple necklace with a plain outfit, natural light portrait'),
  ('fashion', '청바지 인생핏, 지금 찾아도 됨?', '난 다리 핏 맞는 청바지 하나가 옷장을 반으로 줄인다고 봄. 유행 와이드만 산다는 사람 나와봐.', '청바지는 유행보다 길이·허리가 인격임. 안 맞으면 상의가 다 죽음.', ARRAY['청바지','핏','기본템'], 'A Korean man in his early 20s checking jeans fit in a shop mirror, natural stance, no logos'),
  ('fashion', '비 오는 날 코디, 기능이 패션임?', '난 젖지 않는 게 제일 세련됐다고 봄. 예쁜 신발 버리고 가는 거 현타임. 감성 레인부츠 반대파 논리 들어봄.', '비 오는 날은 방수가 코디임. 젖은 청바지가 제일 티 남.', ARRAY['비','코디','기능'], 'A Korean woman in her early 20s in a simple raincoat and sneakers on a wet Seoul street, candid'),
  ('fashion', '편집샵 vs 기본몰, 어디가 이득임?', '난 기본몰에서 반복 구매가 실패값이 낮다고 봄. 편집샵 한 방이 스타일이라는 쪽 나와봐.', '편집샵은 영감이고 기본몰은 실전임. 매일 입을 옷이 진짜 옷장임.', ARRAY['편집샵','가성비','쇼핑'], 'A Korean man in his early 20s comparing a simple tee in hand with a boutique rack behind him, deciding'),

  -- ───────── 맛집 추가 ─────────
  ('맛집', '홍대 골목 탐방, 메인거리보다 맞음?', '난 홍대 안쪽 골목이 간판 전쟁보다 탐방이라고 봄. 메인거리 인증파 논리 가져와.', '홍대는 네온이 아니라 골목 회전임. 큰길만 걸으면 그 동네를 안 본 거임.', ARRAY['홍대','골목','탐방'], 'A Korean woman in her early 20s turning into a Hongdae side alley toward a small eatery, night lights'),
  ('맛집', '을지로 노포, 힙한 신상보다 탐방임?', '난 자리 좁고 오래된 집이 그 지역 온도라고 봄. 인테리어 신상만 탐방이라는 사람 들어와.', '노포는 촌내가 아니라 회전과 손맛의 기록임. 예쁜 집만 가면 동네가 안 보임.', ARRAY['을지로','노포','탐방'], 'A Korean man in his early 20s sitting at a cramped old restaurant counter in Euljiro, steam, candid'),
  ('맛집', '한강 근처 집, 뷰가 탐방 이유 됨?', '난 먹고 나서 강 걷는 동선이 그 집 값이라고 봄. 음식만 보면 된다는 쪽 반박해봐.', '한강 근처는 식사 플러스 동선임. 뷰만 보고 맛이 없으면 그건 풍경임.', ARRAY['한강','뷰','탐방'], 'Two Korean people in their early 20s walking along the Hangang after a meal, evening, casual clothes'),
  ('맛집', '예약제 집, 웨이팅보다 탐방 이득임?', '난 시간 맞춰 들어가는 게 줄 서는 체력보다 이득이라고 봄. 줄이 맛의 증거라는 사람 나와봐.', '예약은 편법이 아니라 일정 관리임. 한 시간 줄이 그 집 급을 증명하진 않음.', ARRAY['예약','웨이팅','맛집'], 'A Korean woman in her early 20s checking a reservation on her phone at a restaurant door, on time'),
  ('맛집', '주차 되는 집, 탐방 실력에 넣어도 됨?', '난 차 오는 친구 있으면 주차가 그 집 인프라라고 봄. 맛만 보면 된다는 쪽 논리 들어봄.', '주차는 사치가 아니라 동선임. 빙빙 돌다 화나면 그 집 음식이 먼저 식음.', ARRAY['주차','맛집','동선'], 'A Korean man in his early 20s parking near a small restaurant, looking relieved, residential street'),
  ('맛집', '대학가 분식골목, 핫플보다 탐방임?', '난 학생 회전 빠른 골목이 가격이랑 속도가 정직하다고 봄. 오픈런 핫플만 탐방이라는 사람 들어와.', '대학가는 유행이 아니라 허기 인프라임. 줄이 짧아도 그 맛이 현지임.', ARRAY['대학가','분식','골목'], 'Young Korean people in their early 20s eating at a small tteokbokki stall near a campus, casual'),
  ('맛집', '해장 탐방, 점심 핫플보다 그 지역임?', '난 아침 국밥집이 그 동네 생존 맛집이라고 봄. 브런치만 탐방이라는 쪽 나와봐.', '해장은 낭만이 아니라 회복 루트임. 문이 일찍 열리는 집이 지역을 먹임.', ARRAY['해장','국밥','탐방'], 'A Korean woman in her early 20s eating hangover soup in the morning at a no-frills restaurant, tired but comforted'),
  ('맛집', '평일 점심 탐방이 주말 오픈런보다 맞음?', '난 평일 점심이 서비스랑 자리가 정직하다고 봄. 주말 줄이 진리라는 사람 반박해봐.', '주말 오픈런은 인기이지 탐방 실력이 아님. 평일 빈자리가 그 집 본판임.', ARRAY['평일','점심','탐방'], 'A Korean man in his early 20s being seated immediately at a weekday lunch restaurant, relaxed'),

  -- ───────── 라이프 스타일: 취향·상황·선택·트렌드 ─────────
  ('lifestyle', '아침형 인간이 이득임?', '난 아침이 하루 선택지를 연다고 봄. 밤이 집중 시간이라는 사람 나와봐.', '아침형은 성격이 아니라 일정 선점임. 밤샘은 다음 날 선택지를 지움.', ARRAY['아침형','루틴','취향'], 'A Korean woman in her early 20s opening curtains to morning light, mug in hand, small apartment'),
  ('lifestyle', '주말은 집이 진리임?', '난 주말 하루는 집 충전이어야 다음 주가 산다고 봄. 밖돌이파 논리 가져와.', '집 주말은 무기력이 아니라 회복임. 스케줄로 채운 주말은 월요일이 더 김.', ARRAY['주말','집','선택'], 'A Korean man in his early 20s on a couch with a blanket on Saturday morning, relaxed, plants by the window'),
  ('lifestyle', '혼자 영화가 같이 보기보다 맞음?', '난 혼자 보는 게 몰입이라고 봄. 같이 봐야 영화라는 쪽 반박해봐.', '혼영은 외로움이 아니라 취향 보호임. 맞추다 보면 둘 다 반만 봄.', ARRAY['영화','혼자','취향'], 'A Korean woman in her early 20s in a dim cinema seat alone, small popcorn, focused calm face'),
  ('lifestyle', '정주행 배속, 이게 맞음?', '난 1.5배가 시간을 지키는 선택이라고 봄. 원속이 예의라는 사람 들어와.', '배속은 불경이 아니라 시간 배분임. 한 시즌에 주말을 통째로 주는 게 손해임.', ARRAY['정주행','배속','트렌드'], 'A Korean man in his early 20s watching a show on a laptop at a desk, remote in hand, evening'),
  ('lifestyle', '종이책이 전자책보다 남음?', '난 종이 넘기는 감각이 읽기를 끝까지 가게 한다고 봄. 전자책이 짐 없는 진리라는 쪽 나와봐.', '종이책은 낭만이 아니라 집중임. 알림 없는 페이지가 한 권을 끝내게 함.', ARRAY['책','독서','취향'], 'A Korean woman in her early 20s reading a paperback at a small table, phone face down'),
  ('lifestyle', '취미는 하나 깊게가 이득임?', '난 하나 파는 게 여러 개 긁다 마는 것보다 남긴다고 봄. 다재다능파 논리 들어봄.', '취미는 개수가 프로필이 아님. 깊이 있는 하나가 주말을 채움.', ARRAY['취미','선택','취향'], 'A Korean man in his early 20s practicing one hobby at a desk, guitar or sketchbook, focused'),
  ('lifestyle', '홈트가 헬스장보다 맞음?', '난 집 운동이 이동 시간을 아낀다고 봄. 헬스장 분위기파 들어와.', '홈트는 게으름이 아니라 지속임. 가방 싸는 날만 운동이면 루틴이 끊김.', ARRAY['홈트','운동','선택'], 'A Korean woman in her early 20s doing a simple floor workout in a small living room, mat, natural light'),
  ('lifestyle', '러닝은 혼자 뛰는 게 맞음?', '난 혼자 뛰어야 페이스가 내 것이라고 봄. 크루여야 지속된다는 쪽 반박해봐.', '혼자 러닝은 외로움이 아니라 속도 조절임. 맞추다 보면 몸이 먼저 지침.', ARRAY['러닝','혼자','트렌드'], 'A Korean man in his early 20s jogging alone on a riverside path at dawn, ordinary clothes, no logos'),
  ('lifestyle', '팝업스토어 줄, 설렘임 낭비임?', '난 한정 경험을 사러 가는 거라고 봄. 줄 서는 순간 진 거라는 사람 나와봐.', '팝업은 물건보다 그 주 이야기임. 사진만 남고 안 쓰면 그게 낭비임.', ARRAY['팝업','트렌드','줄'], 'A Korean woman in her early 20s waiting in a short line outside a small pop-up shop, curious not posed'),
  ('lifestyle', '굿즈 모으는 거, 과함임?', '난 좋아하는 거 하나 사는 게 기분 예산이라고 봄. 실용만 사라는 쪽 논리 가져와.', '굿즈는 허세가 아니라 취향의 실물임. 서랍에만 있으면 그때부터 짐임.', ARRAY['굿즈','취향','소비'], 'A Korean man in his early 20s placing one small character item on a tidy shelf, pleased, ordinary room'),
  ('lifestyle', '필름 카메라가 폰보다 기록임?', '난 장수 제한이 찍는 장면을 고르게 한다고 봄. 폰이 다 담는다는 사람 반박해봐.', '필름은 감성이 아니라 선택 촬영임. 만 장 갤러리는 나중에 안 봄.', ARRAY['필름','사진','트렌드'], 'A Korean woman in her early 20s holding a simple film camera on a street, about to shoot, candid'),
  ('lifestyle', '개인컵 들고 다니는 거, 이득임?', '난 텀블러가 충동 음료를 줄인다고 봄. 매번 새 컵이 편하다는 쪽 들어와.', '개인컵은 인증이 아니라 습관임. 집 커피 한 잔이 줄 서는 시간을 아낌.', ARRAY['텀블러','습관','선택'], 'A Korean man in his early 20s filling a plain tumbler at home before leaving, morning kitchen'),
  ('lifestyle', '식물 키우는 집이 맞음?', '난 화분 하나가 방 온도를 바꾼다고 봄. 관리 귀찮다는 사람 나와봐.', '식물은 인테리어 소품이 아니라 루틴임. 물 주는 날이 집을 보게 함.', ARRAY['식물','방','취향'], 'A Korean woman in her early 20s watering one small plant by a window, casual home clothes'),
  ('lifestyle', '방 조명은 간접등이 진리임?', '난 천장 형광이 방을 사무실로 만든다고 봄. 밝아야 산다는 쪽 논리 들어봄.', '간접등은 꾸밈이 아니라 저녁 컨디션임. 눈이 편해야 집에 있고 싶음.', ARRAY['조명','방','취향'], 'A Korean man in his early 20s sitting in a room lit by a warm floor lamp, phone aside, evening'),
  ('lifestyle', '알림 끄기가 생산임?', '난 배너 끄면 집중이 돌아온다고 봄. 실시간 답장이 매너라는 사람 반박해봐.', '알림은 정보가 아니라 호출임. 모아서 보는 게 하루를 지킴.', ARRAY['알림','폰','선택'], 'A Korean woman in her early 20s turning on do-not-disturb and setting the phone face down, desk'),
  ('lifestyle', '폰은 침실 밖에 두는 게 맞음?', '난 충전을 거실에 두면 잠이 먼저 온다고 봄. 침대 옆이 편리하다는 쪽 들어와.', '침실 폰은 알람 핑계임. 한 번 누우면 스크롤이 수면을 가져감.', ARRAY['수면','폰','습관'], 'A Korean man in his early 20s leaving his phone on a living-room shelf and walking toward the bedroom'),
  ('lifestyle', '가계부 쓰는 거, 스트레스임 이득임?', '난 쓴 돈을 봐야 다음 선택이 줄어든다고 봄. 기분 나쁘다는 사람 나와봐.', '가계부는 잔소리가 아니라 선택 기록임. 안 적으면 같은 결제를 반복함.', ARRAY['가계부','돈','선택'], 'A Korean woman in her early 20s checking a simple spending note beside a card, calm kitchen table'),
  ('lifestyle', '여행은 즉흥이 맞음?', '난 큰 틀만 잡고 비우는 날이 여행이라고 봄. 분 단위 계획파 논리 가져와.', '즉흥은 무계획이 아니라 여백임. 동선에 쫓기면 현지보다 시간을 봄.', ARRAY['여행','즉흥','선택'], 'A Korean man in his early 20s with a small backpack at a quiet station, deciding which way to walk'),
  ('lifestyle', '혼행이 같이 가기보다 이득임?', '난 혼자 가면 먹고 걷는 속도가 내 것이라고 봄. 동행이 추억이라는 쪽 반박해봐.', '혼행은 외로움 자랑이 아니라 일정 자유임. 맞추다 보면 여행이 회의가 됨.', ARRAY['혼행','여행','취향'], 'A Korean woman in her early 20s sitting alone at a small-town bus stop with a day bag, content'),
  ('lifestyle', '국내 여행이 지금 이득임?', '난 이동이 짧은 국내가 휴가를 실제로 쉬게 한다고 봄. 해외여야 여행이라는 사람 들어와.', '국내는 타협이 아니라 밀도임. 공항에서 하루를 쓰면 휴가가 이동이 됨.', ARRAY['국내여행','휴가','선택'], 'A Korean man in his early 20s looking out a train window at Korean countryside, small bag on the seat'),

  -- ───────── 연애: 호감·사랑·썸·사귐·이별 ─────────
  ('romance', '사귀자, 언제 말하는 게 맞음?', '난 호감이 식기 전에 말하는 게 서로 덜 헤맨다고 봄. 분위기만 보자는 쪽 나와봐.', '확답은 부담이 아니라 방향임. 썸만 길면 둘 다 다른 가능성을 붙잡음.', ARRAY['사귀자','고백','썸'], 'A Korean woman in her early 20s pausing before speaking across a quiet cafe table, hopeful'),
  ('romance', '연애 공개, 인스타에 올려도 됨?', '난 둘만 아는 연애가 더 오래간다고 봄. 공개해야 진심이라는 사람 반박해봐.', '비공개는 숨기는 게 아니라 관계 보호임. 피드용 커플은 빨리 지침.', ARRAY['공개연애','인스타','연애'], 'A Korean man in his early 20s putting his phone away while sitting with a partner, candid cafe'),
  ('romance', '이성 친구, 연애 중에도 됨?', '난 연애 전 친구를 끊는 게 더 이상하다고 봄. 단둘이 만남은 선 그어야 한다는 쪽 들어와.', '친구와 애인은 자리가 다름. 숨기면 그때부터 문제임.', ARRAY['이성친구','경계','연애'], 'A Korean woman in her early 20s waving to a friend on the street while holding a partner hand loosely'),
  ('romance', '질투하는 거, 사랑임 구속임?', '난 질투를 말로 꺼내는 게 삼키는 것보다 낫다고 봄. 쿨해야 성숙이라는 사람 논리 가져와.', '질투는 사랑이 아니라 불안의 신호임. 확인이 반복되면 구속이 됨.', ARRAY['질투','신뢰','연애'], 'A Korean man in his early 20s looking at a phone with a worried face, partner beside him out of focus'),
  ('romance', '싸움 나면 누가 먼저 연락함?', '난 먼저 톡하는 쪽이 관계를 살린다고 봄. 식힐 시간이 필요하다는 쪽 나와봐.', '침묵은 정리 시간이 아니라 벌이 되기 쉬움. 한 줄이 밤을 넘김.', ARRAY['싸움','연락','연애'], 'A Korean woman in her early 20s typing a short message at night, serious but calm'),
  ('romance', '애정 표현, 매일 해야 함?', '난 매일 한 마디가 관계를 유지한다고 봄. 있을 때만 해도 충분하다는 사람 반박해봐.', '표현은 이벤트가 아니라 온도임. 특별한 날에만 하면 평일이 비움.', ARRAY['애정','표현','연애'], 'A Korean man in his early 20s sending a simple goodnight text, small smile, bedroom lamp'),
  ('romance', '커플 여행, 초반에 가도 됨?', '난 같이 이동해 봐야 호흡이 보인다고 봄. 사귄 지 오래돼야 간다는 쪽 들어와.', '여행은 시험이 아니라 시간 밀도임. 초반이라도 일정이 짧으면 됨.', ARRAY['커플여행','데이트','연애'], 'Two Korean people in their early 20s with small bags at a train platform, easy not dramatic'),
  ('romance', '위치 공유, 신뢰임 감시임?', '난 늦을 때 안심하라고 켜 두는 거라고 봄. 위치는 감시라는 사람 논리 들어봄.', '공유는 합의면 배려임. 끄면 의심부터 하면 그때 감시가 됨.', ARRAY['위치공유','신뢰','연애'], 'A Korean woman in her early 20s showing a map pin to a partner, both looking at one phone, calm'),
  ('romance', '권태기, 버티는 게 맞음?', '난 설레임이 줄어도 루틴이 남으면 연애라고 봄. 심심하면 끝내야 한다는 쪽 나와봐.', '권태는 실패 선언이 아님. 대화 없이 버티기만 하면 그때 끝임.', ARRAY['권태','연애','고민'], 'A Korean man in his early 20s sitting with a partner on a couch, quiet but together, evening'),
  ('romance', '이별 통보, 만나서 하는 게 맞음?', '난 얼굴 보고 말하는 게 최소한의 매너라고 봄. 톡이 덜 잔인하다는 사람 반박해봐.', '이별은 결론이지 처벌이 아님. 잠수보다 한 번의 대화가 남음.', ARRAY['이별','매너','연애'], 'A Korean woman in her early 20s sitting across a quiet table, serious gentle expression, daytime'),
  ('romance', '재회, 한 번은 기회임?', '난 이유가 달라졌으면 한 번은 다시 볼 수 있다고 봄. 끝난 건 끝난 거라는 쪽 들어와.', '재회는 미련 소비가 아님. 같은 싸움만 반복되면 그때 닫아야 함.', ARRAY['재회','이별','연애'], 'A Korean man in his early 20s meeting someone at a park bench, cautious hopeful face'),
  ('romance', '썸 기간, 한 달이면 김?', '난 한 달이면 마음을 말할 타이밍이라고 봄. 더 봐야 안 다친다는 사람 나와봐.', '긴 썸은 안전이 아니라 소모임. 확답이 없어도 방향은 있어야 함.', ARRAY['썸','기간','연애'], 'A Korean woman in her early 20s checking the calendar on her phone after a date, thoughtful'),
  ('romance', '확답 요구, 부담임 매너임?', '난 어디쯤인지 묻는 게 서로 예의를 아낀다고 봄. 재촉이라는 쪽 논리 가져와.', '확답은 들이댐이 아니라 정리임. 애매한 호감이 제일 오래 아픔.', ARRAY['확답','썸','연애'], 'A Korean man in his early 20s talking honestly over two drinks, nervous but direct'),
  ('romance', '데이트 코스, 번갈아 정하는 게 맞음?', '난 한 사람이 항상 짜면 취향이 연애가 된다고 봄. 잘하는 쪽이 맡으면 된다는 사람 반박해봐.', '코스는 취향 존중임. 번갈아 정해야 둘 다 기대가 생김.', ARRAY['데이트','코스','연애'], 'Two Korean people in their early 20s looking at a phone map together on a sidewalk, deciding'),
  ('romance', '애칭, 있어야 연애임?', '난 이름 부르는 온도면 충분하다고 봄. 애칭 없으면 맘이 식은 거라는 쪽 들어와.', '애칭은 증거가 아니라 놀이임. 없어도 편하면 그게 애정임.', ARRAY['애칭','호칭','연애'], 'A Korean woman in her early 20s laughing at a nickname on a chat screen, partner beside her'),
  ('romance', '스킨십 속도, 맞추는 게 먼저임?', '난 느린 쪽에 맞추는 게 다정이라고 봄. 표현이 사랑이라는 사람 나와봐.', '속도는 애정 점수가 아님. 불편한 속도를 참으면 연애가 시험이 됨.', ARRAY['스킨십','속도','연애'], 'A Korean man in his early 20s walking beside someone, hands close but not forced, evening street'),
  ('romance', '미래 얘기, 사귄 지 얼마 만에 함?', '난 방향이 다르면 빨리 아는 게 덜 다친다고 봄. 아직 이르다는 쪽 논리 들어봄.', '미래 얘기는 압박이 아니라 지도임. 피하기만 하면 가정만 커짐.', ARRAY['미래','연애','대화'], 'A Korean woman in her early 20s talking quietly with a partner at a late cafe, serious warm light'),
  ('romance', '미안할 때 먼저 사과가 이김?', '난 누가 맞는지보다 먼저 푸는 쪽이 관계를 남긴다고 봄. 맞는 말이 먼저라는 사람 반박해봐.', '사과는 패배가 아님. 옳음을 지키다 밤을 넘기면 주제는 사라짐.', ARRAY['사과','싸움','연애'], 'A Korean man in his early 20s saying sorry across a small table, sincere, no drama'),
  ('romance', '혼자만의 시간, 연애 중에 필요함?', '난 각자 저녁 하나가 연애를 덜 지치게 한다고 봄. 항상 같이 있어야 사랑이라는 쪽 나와봐.', '혼자 시간은 거리가 아니라 충전임. 붙잡히면 애정이 일정표가 됨.', ARRAY['개인시간','경계','연애'], 'A Korean woman in her early 20s reading alone at home, a text from a partner left unread for a moment'),
  ('romance', '부모님 인사, 이 타이밍이 맞음?', '난 서로 확신이 생긴 뒤에 인사가 예의라고 봄. 일찍 보여줘야 진심이라는 사람 들어와.', '인사는 이벤트가 아니라 관계의 다음 문임. 준비 없이 가면 둘 다 긴장만 남음.', ARRAY['인사','부모님','연애'], 'A Korean man in his early 20s straightening his jacket before meeting someone, nervous small smile',

  -- ───────── 200개로 늘린 추가 주제 ─────────
  ('eternal_quest', '카공 콘센트, 먼저 꽂는 게 맞음?', '난 앉자마자 충전기부터 꽂는 게 생존이라고 봄. 눈치 보다 방전되는 거 손해. 양보파 나와봐.', '카공은 콘센트가 자리값임. 음료는 그 자리에 대한 입장권임.', ARRAY['카공','콘센트','매너'], 'A Korean woman in her early 20s plugging a charger into a cafe wall outlet as she sits down, laptop closed, candid'),
  ('eternal_quest', '중고거래 네고, 예의임 실례임?', '난 시세 보고 한 번 묻는 건 예의라고 봄. 터무니없이 깎자는 건 시간 도둑임. 정가파 반박해봐.', '네고는 한 번이면 충분함. 세 번 깎으면 그 거래는 이미 불편해짐.', ARRAY['중고','네고','매너'], 'A Korean man in his early 20s photographing a small used item on a desk before a meetup, natural light'),
  ('eternal_quest', '새벽 배송 소리, 참는 게 맞음?', '난 새벽에 문 앞 소음은 한 번 말하는 게 맞다고 봄. 그냥 참는 게 어른이라는 쪽 들어와.', '새벽 소음은 편리의 뒷면임. 한 번 요청이 층간 감정보다 깔끔함.', ARRAY['배송','소음','자취'], 'A Korean woman in her early 20s glancing at her apartment door at dawn, a small parcel outside, sleepy'),
  ('eternal_quest', '에어컨 온도, 누가 맞추는 게 맞음?', '난 더위 타는 사람 기준으로 맞추고 겉옷을 더하는 게 맞다고 봄. 추위파 논리 가져와.', '온도는 다수결이 아니라 못 버티는 쪽임. 겉옷은 개인이 해결함.', ARRAY['에어컨','온도','자취'], 'A Korean man in his early 20s adjusting a small air conditioner remote in a shared room, light jacket on a chair'),
  ('eternal_quest', '분리수거, 하루 미뤄도 됨?', '난 당일 버리는 게 방이 안 죽는 길이라고 봄. 모아서 한 번에가 효율이라는 사람 나와봐.', '분리수거는 미루는 순간 현관이 창고가 됨. 당일이 제일 짧음.', ARRAY['분리수거','자취','습관'], 'A Korean woman in her early 20s sorting recycling into bags by an apartment door, evening, casual clothes'),
  ('eternal_quest', '도서관 가방 맡기기, 매너임?', '난 자리 비울 거면 가방도 가져가는 게 맞다고 봄. 잠시 맡김은 관례라는 쪽 반박해봐.', '가방 맡기기는 자리 독임. 화장실도 표시 없이 오래면 양보가 맞음.', ARRAY['도서관','자리','매너'], 'A Korean man in his early 20s picking up his backpack from a library seat before stepping away, quiet room'),
  ('eternal_quest', '헬스장 기구, 쉬는 시간 한 세트가 끝임?', '난 세트 사이에 폰 보면 줄이 생긴다고 봄. 휴식도 운동이라는 사람 논리 들어봄.', '기구는 점유가 아니라 교대임. 한 세트 끝나면 눈이 마주친 사람한테 넘김.', ARRAY['헬스','기구','매너'], 'A Korean woman in her early 20s stepping back from a gym machine to let someone else start, ordinary gym, no logos'),
  ('eternal_quest', '단체 메뉴, 다수결이 맞음?', '난 못 먹는 사람 하나면 그 집은 빼는 게 맞다고 봄. 다수결이 민주주의라는 쪽 나와봐.', '메뉴는 표수가 아니라 제외 조건임. 한 명이 못 먹으면 그 모임이 불편해짐.', ARRAY['모임','메뉴','배려'], 'Young Korean people in their early 20s looking at one phone menu at a restaurant entrance, deciding together'),
  ('eternal_quest', '우산 안 빌려주는 거, 매정임?', '난 우산은 빌려주면 돌아오지 않는 물건이라고 봄. 비 맞히는 게 매정이라는 사람 들어와.', '우산은 호의 한 번이면 됨. 기대하고 빈손으로 나오는 게 더 부담임.', ARRAY['우산','호의','매너'], 'A Korean man in his early 20s hesitating at a doorway with one umbrella while rain hits the street'),
  ('eternal_quest', '필기는 손글씨가 더 남음?', '난 손으로 적어야 시험 전에 기억이 난다고 봄. 타자가 빠르다는 쪽 논리 가져와.', '손글씨는 느린 게 아니라 한 번 더 읽는 거임. 받아쓰기 속도만 보면 짐.', ARRAY['필기','공부','습관'], 'A Korean woman in her early 20s writing in a notebook at a library desk, phone face down, daylight'),
  ('eternal_quest', '공유 오피스, 카페보다 이득임?', '난 시간당 내는 자리가 눈치 없는 집중이라고 봄. 카페 음료가 더 싸다는 사람 반박해봐.', '공유 오피스는 자리 임대임. 카페는 두 잔째부터 민망해짐.', ARRAY['공유오피스','집중','카공'], 'A Korean man in his early 20s working at a quiet shared desk with a laptop, ordinary coworking corner, no logos'),
  ('eternal_quest', '카풀 기름값, 따로 내는 게 맞음?', '난 탈 때마다 기름값을 보내는 게 우정이라고 봄. 운전한 정이 크다는 쪽 나와봐.', '카풀은 호의가 기본값이 아님. 금액이 적어야 다음에도 태워줌.', ARRAY['카풀','기름값','정산'], 'A Korean woman in her early 20s in a passenger seat sending a small transfer, driver friend looking ahead, daytime'),
  ('eternal_quest', '택배 박스, 당일 치우는 게 매너임?', '난 박스는 받은 날 버리는 게 현관 매너라고 봄. 분리수거 날까지 모아도 된다는 쪽 들어와.', '박스는 선물이 아니라 부피임. 하루만 쌓여도 복도가 좁아짐.', ARRAY['택배','박스','자취'], 'A Korean man in his early 20s flattening a cardboard box in a small entryway, tidy apartment'),
  ('eternal_quest', '친구 집, 양말 신고 들어가도 됨?', '난 주인이 신으라고 하기 전에 벗는 게 기본이라고 봄. 양말이 예의라는 사람 반박해봐.', '신발이 끝나면 양말도 눈치임. 물어보는 한 마디가 바닥을 지킴.', ARRAY['방문','양말','예절'], 'A Korean woman in her early 20s pausing at a friend apartment entrance, shoes off, looking at the floor'),
  ('fashion', '옷 수선, 새로 사는 것보다 이득임?', '난 기장 수선이 새 옷 한 벌보다 핏을 살린다고 봄. 수선집에 갈 시간에 산다는 쪽 나와봐.', '수선은 귀찮음이 아니라 옷 수명임. 안 맞는 새 옷이 더 비쌈.', ARRAY['수선','핏','가성비'], 'A Korean woman in her early 20s holding a hemmed pair of trousers up in a small room, mirror nearby'),
  ('fashion', '같은 옷 반복, 게으름임 시그니처임?', '난 매일 비슷한 조합이 실패를 줄인다고 봄. 매일 달라야 패션이라는 사람 논리 들어봄.', '반복은 게으름이 아니라 유니폼임. 잘 맞는 한 벌이 아침을 줄임.', ARRAY['반복','유니폼','코디'], 'A Korean man in his early 20s wearing the same simple jacket and tee, weekday sidewalk, candid'),
  ('fashion', '후드티, 외출복으로 됨?', '난 깨끗한 후드가 약속 장소까지 커버된다고 봄. 카라가 있어야 외출이라는 쪽 들어와.', '후드는 잠옷이 아님. 신발만 정돈되면 저녁 약속도 됨.', ARRAY['후드','외출','캐주얼'], 'A Korean woman in her early 20s walking to a cafe in a clean hoodie and sneakers, evening street'),
  ('fashion', '컬러 양말, 포인트임 과함임?', '난 양말 색깔 하나가 전신을 살린다고 봄. 눈에 띄면 과하다는 사람 반박해봐.', '양말은 숨기는 옷이 아님. 바지 밑으로 한 줄이 코디의 마침표임.', ARRAY['양말','포인트','코디'], 'A Korean man in his early 20s sitting on a bench, a bright sock showing above a simple sneaker, candid'),
  ('fashion', '계절 옷 정리, 꼭 해야 함?', '난 한 철 지난 옷을 상자 넣는 날이 옷장 리셋이라고 봄. 꺼내 입으면 된다는 쪽 나와봐.', '정리는 행사임. 안 하면 아침마다 여름 옷이 겨울을 막음.', ARRAY['정리','옷장','계절'], 'A Korean woman in her early 20s folding off-season clothes into a box on the floor, closet open'),
  ('fashion', '카라 티, 일상에도 맞음?', '난 카라 티가 후드보다 약속 범위가 넓다고 봄. 편하려면 라운드만 입자는 사람 들어와.', '카라는 딱딱함이 아니라 외출 스위치임. 청바지랑 입으면 과하지 않음.', ARRAY['카라티','일상','코디'], 'A Korean man in his early 20s in a plain polo and jeans at a casual lunch table, no logos'),
  ('fashion', '와이드 팬츠, 아직도 편함 이김?', '난 와이드가 앉는 하루를 편하게 한다고 봄. 슬림이 정리돼 보인다는 쪽 논리 가져와.', '밑단이 넓어도 허리가 맞으면 정돈임. 편해야 오후에 표정이 남음.', ARRAY['와이드','팬츠','편함'], 'A Korean woman in her early 20s walking in wide trousers and a simple tee, Seoul crosswalk, candid'),
  ('fashion', '코트 하나, 겨울이 커버됨?', '난 무겁지 않은 코트 하나가 패딩 여러 벌보다 낫다고 봄. 길이별로 있어야 한다는 사람 나와봐.', '코트는 개수가 아니라 기장임. 매일 입을 하나가 진짜 겨울옷임.', ARRAY['코트','겨울','기본템'], 'A Korean man in his early 20s buttoning one simple coat at an apartment door, winter light, no logos'),
  ('fashion', '실내화, 따로 두는 게 패션임?', '난 밖에서 신은 신발을 방에 안 들이는 게 코디의 시작이라고 봄. 귀찮다는 쪽 반박해봐.', '실내화는 위생이자 집 옷임. 운동화 그대로면 방이 거리랑 같아짐.', ARRAY['실내화','집','습관'], 'A Korean woman in her early 20s switching to plain house slippers at the entrance, outdoor shoes set aside'),
  ('fashion', '모자, 로고 없는 게 맞음?', '난 글자 없는 모자가 얼굴이 산다고 봄. 로고가 포인트라는 사람 논리 들어봄.', '모자는 그늘이지 간판이 아님. 심플해야 어떤 옷에도 붙음.', ARRAY['모자','심플','코디'], 'A Korean man in his early 20s wearing a plain unbranded cap on a sunny street, natural face'),
  ('fashion', '옷 사진 찍고 사기, 실패를 줄임?', '난 피팅 사진을 다음날 다시 보는 게 충동을 거른다고 봄. 즉석 결제가 감각이라는 쪽 나와봐.', '사진은 인증이 아니라 쿨링임. 하루 지나도 갖고 싶으면 그때 삼.', ARRAY['피팅','쇼핑','충동'], 'A Korean woman in her early 20s taking a mirror photo of an outfit in a fitting room, deciding, no logos'),
  ('fashion', '니트는 한 장만 있어도 됨?', '난 색 하나 잘 받는 니트가 겨울 상의를 대체한다고 봄. 패턴 니트 수집파 들어와.', '니트는 종류보다 목선임. 매일 입는 한 장이 옷장 주인공임.', ARRAY['니트','겨울','기본템'], 'A Korean man in his early 20s pulling on a plain knit sweater at home, morning, soft light'),
  ('fashion', '벨트, 아직도 필요한 아이템임?', '난 허리만 잡아줘도 실루엣이 산다고 봄. 밴딩이면 충분하다는 사람 반박해봐.', '벨트는 포멀용이 아니라 비율임. 늘어진 허리만 잡아도 다른 옷이 됨.', ARRAY['벨트','실루엣','코디'], 'A Korean woman in her early 20s fastening a simple belt over trousers, bedroom mirror, candid'),
  ('맛집', '익선동 골목, 줄보다 분위기가 탐방임?', '난 익선은 줄 선 집보다 골목 공기가 탐방이라고 봄. 웨이팅이 그 동네라는 쪽 나와봐.', '한옥 골목은 자리보다 걷는 시간이 남음. 줄만 서면 어느 동네든 같아짐.', ARRAY['익선동','골목','탐방'], 'A Korean woman in her early 20s walking a narrow hanok alley in Ikseon-dong, looking at small shopfronts'),
  ('맛집', '한남 언덕집, 뷰가 탐방값임?', '난 먹고 내려다보는 자리가 그 집 이유라고 봄. 음식만 보면 된다는 사람 논리 가져와.', '언덕집은 동선이 메뉴임. 뷰가 없는데 힘들어서 오른 거면 다음엔 안 감.', ARRAY['한남','뷰','탐방'], 'A Korean man in his early 20s sitting by a hillside window after a meal, city view, relaxed'),
  ('맛집', '화장실 깨끗한 집, 재방문 이유 됨?', '난 화장실이 그 집 관리라고 봄. 맛있으면 상관없다는 쪽 반박해봐.', '화장실은 숨은 서비스임. 한 번 불편하면 그 골목이 식음.', ARRAY['화장실','서비스','재방문'], 'A Korean woman in her early 20s washing her hands in a small clean restaurant restroom, ordinary, candid'),
  ('맛집', '오픈 키친, 그 집 구경거리임?', '난 불이 보이는 집이 탐방 재미라고 봄. 자리는 조용해야 한다는 사람 들어와.', '오픈 키친은 쇼가 아니라 신뢰임. 손이 보이면 대기가 덜 지루함.', ARRAY['오픈키친','분위기','탐방'], 'A Korean man in his early 20s watching cooks at an open kitchen counter, small restaurant, interested'),
  ('맛집', '루프탑 자리, 탐방에 넣어도 됨?', '난 올라가서 먹는 한 끼가 그 동네 기억이라고 봄. 바람 불면 실내가 진리라는 쪽 나와봐.', '루프탑은 사진용이 아니라 저녁 공기임. 맛까지 되면 그 집이 남음.', ARRAY['루프탑','저녁','탐방'], 'Two Korean people in their early 20s at a simple rooftop table at dusk, city behind them, no logos'),
  ('맛집', '골목 포장마차, 매장보다 그 지역임?', '난 포장 천막이 그 동네 밤 온도라고 봄. 의자가 있어야 탐방이라는 사람 반박해봐.', '포장마차는 간이 아님. 서서 먹는 그 블록이 지역임.', ARRAY['포장마차','골목','밤'], 'A Korean woman in her early 20s standing at a small street stall at night, steam, casual clothes'),
  ('맛집', '백화점 맛집층, 탐방 동선임?', '난 비 오는 날 백화점 층이 탐방 대체 루트라고 봄. 길거리만 탐방이라는 쪽 들어와.', '백화점 층은 가짜 골목이 아님. 여러 집을 날씨 없이 비교하는 동선임.', ARRAY['백화점','맛집층','동선'], 'A Korean man in his early 20s walking a department-store food floor, looking at stall signs, rainy day clothes'),
  ('맛집', '역에서 10분, 그 거리가 탐방임?', '난 출구에서 걷는 10분이 그 집을 고르는 이유라고 봄. 역세권만 진리라는 사람 나와봐.', '가까운 집은 편리지 탐방이 아님. 골목 하나 더 들어가야 지역이 보임.', ARRAY['역세권','도보','탐방'], 'A Korean woman in her early 20s walking ten minutes from a subway exit toward a small restaurant, map on phone'),
  ('맛집', '사장님이 자리 안내, 그 집이 급임?', '난 주문 전에 자리를 봐 주는 집이 다시 간다고 봄. 셀프가 빠르다는 쪽 논리 들어봄.', '안내는 격식이 아니라 동선임. 서서 헤매면 그 집 첫인상이 김.', ARRAY['안내','서비스','맛집'], 'A Korean restaurant owner in their 40s gesturing a young Korean guest in their early 20s toward an open table'),
  ('맛집', '테라스 자리, 실내보다 그 집임?', '난 바깥 테이블이 그 카페를 온 이유라고 봄. 에어컨 실내가 진리라는 사람 반박해봐.', '테라스는 계절 한정 메뉴임. 자리 없으면 다른 날이 맞음.', ARRAY['테라스','카페','자리'], 'A Korean man in his early 20s sitting at a small terrace table with an iced drink, shade, candid'),
  ('맛집', '라스트 오더, 탐방 일정에 넣음?', '난 마지막 주문 시간을 보고 집을 고른다고 봄. 문 닫기 직전이 낭만이라는 쪽 나와봐.', '라스트 오더는 마감 독촉임. 여유 있게 앉는 집이 재방문됨.', ARRAY['라스트오더','시간','탐방'], 'A Korean woman in her early 20s checking a restaurant closing time on the door, early evening'),
  ('맛집', '메뉴판 없는 집, 탐방 모험임?', '난 오늘 나온 것만 내는 집이 지역 탐방이라고 봄. 메뉴가 있어야 안심이라는 사람 들어와.', '메뉴판 없음은 불친절이 아니라 그날의 재료임. 못 먹으면 미리 말하면 됨.', ARRAY['메뉴','노포','탐방'], 'A Korean man in his early 20s listening as a server describes today dishes, small restaurant, no menu board'),
  ('맛집', '동네 단골집, 핫플보다 실력임?', '난 이름 없는 단골이 탐방의 끝이라고 봄. 새로 연 집만 기록이라는 쪽 반박해봐.', '단골은 인증이 아니라 반복임. 세 번 간 집이 그 사람 지도임.', ARRAY['단골','동네','탐방'], 'A Korean woman in her early 20s being recognized by staff at a small neighborhood restaurant, warm candid'),
  ('맛식', '식빵 가장자리, 그 식감이 맛임?', '난 껍질 쪽이 식빵의 이유라고 봄. 부드러운 속만 진리라는 사람 나와봐.', '가장자리는 태운 게 아니라 씹는 맛임. 속만 먹으면 다음 장이 싱거움.', ARRAY['식빵','식감','맛'], 'A Korean man in his early 20s eating a toast crust at a small breakfast table, butter nearby'),
  ('맛식', '아이스 아메리카노, 연해야 맛임?', '난 연한 아이스가 오래 마신다고 봄. 진해야 커피라는 쪽 논리 가져와.', '쓴맛 농도는 취향이 아니라 속도임. 너무 진하면 반 잔에 끝남.', ARRAY['아메리카노','커피','맛'], 'A Korean woman in her early 20s sipping a light iced coffee at a window seat, relaxed'),
  ('맛식', '김치 익은 맛, 이게 진리임?', '난 살짝 익은 김치가 밥이랑 제일 맞는다고 봄. 갓 담근 아삭파 반박해봐.', '익은 김치는 향이 맛임. 너무 일찍 먹으면 짠맛만 남음.', ARRAY['김치','발효','맛'], 'A Korean man in his early 20s taking ripe kimchi with rice, home table, close candid'),
  ('맛식', '소스 따로, 튀김 식감이 삼?', '난 소스를 따로 둬야 튀김이 끝까지 산다고 봄. 뿌려야 맛이라는 사람 들어와.', '소스는 선택임. 처음부터 적시면 마지막 한 입이 다른 음식이 됨.', ARRAY['튀김','소스','식감'], 'A Korean woman in her early 20s dipping one piece of fried food, sauce in a small dish beside the plate'),
  ('맛식', '라면 스프 반, 간이 맛임?', '난 스프를 반만 넣는 게 국물의 여운이라고 봄. 전부 넣어야 라면이라는 쪽 나와봐.', '반은 싱거움이 아니라 조절임. 면이 스프를 더 먹으면 끝이 짜짐.', ARRAY['라면','간','맛'], 'A Korean man in his early 20s pouring only part of a ramen soup packet into a pot, small kitchen'),
  ('맛식', '초밥은 밥 온도가 맛임?', '난 밥이 살짝 따뜻해야 그 초밥이라고 봄. 생선만 보자는 사람 논리 들어봄.', '밥 온도는 간임. 차가우면 식초가 먼저 남음.', ARRAY['초밥','밥','온도'], 'A Korean woman in her early 20s lifting a piece of sushi, rice visible, small counter seat'),
  ('맛식', '튀김옷 얇은 게 맛임?', '난 옷이 얇아야 재료가 보인다고 봄. 두꺼운 바삭이 진리라는 쪽 반박해봐.', '얇은 옷은 겸손이 아니라 식감 배분임. 옷만 먹으면 재료가 짐.', ARRAY['튀김옷','식감','맛'], 'A Korean man in his early 20s breaking a lightly battered fried piece, filling visible, casual table'),
  ('맛식', '디저트는 쓴맛이 있어야 함?', '난 마지막에 쓴맛이 단맛을 끊는다고 봄. 달아야 디저트라는 사람 나와봐.', '쓴맛은 어른 취향 자랑이 아님. 한 입 리셋이 다음 조각을 가능하게 함.', ARRAY['디저트','쓴맛','맛'], 'A Korean woman in her early 20s tasting a bitter chocolate dessert, thoughtful smile, cafe'),
  ('맛식', '국수 육수, 멸치가 기본임?', '난 멸치 육수가 국수의 바닥이라고 봄. 고기 육수가 진리라는 쪽 들어와.', '멸치는 구수함임. 고기만 있으면 면이 무거워짐.', ARRAY['국수','육수','멸치'], 'A Korean man in his early 20s eating noodles in a clear anchovy broth, steam, small shop'),
  ('맛식', '에어프라이어, 튀김 맛이 남?', '난 에어가 튀김의 바삭을 집에서도 만든다고 봄. 기름 튀김만 진짜라는 사람 반박해봐.', '에어는 타협이 아니라 온도임. 겉이 서면 그 식감은 남음.', ARRAY['에어프라이어','튀김','식감'], 'A Korean woman in her early 20s taking crispy food from an air fryer in a small kitchen, pleased'),
  ('맛식', '과일 먼저, 식단이 더 맛있음?', '난 식사 전에 과일이 단맛 폭주를 줄인다고 봄. 식후 과일이 진리라는 쪽 나와봐.', '과일은 디저트 순서가 아니라 첫 단맛임. 먼저 먹으면 다음 끼가 덜 달아짐.', ARRAY['과일','식단','순서'], 'A Korean man in his early 20s eating sliced fruit before a meal, small plate, home table'),
  ('맛식', '견과 한 줌, 간식 맛으로 됨?', '난 견과가 과자보다 한 끼 사이를 버틴다고 봄. 달콤해야 간식이라는 사람 논리 가져와.', '견과는 건강 숙제가 아니라 고소함임. 짜면 한 줌에서 끝남.', ARRAY['견과','간식','맛'], 'A Korean woman in her early 20s eating a small handful of nuts at a desk, afternoon, not posed'),
  ('맛식', '물김치, 밥도둑 맛임?', '난 물김치 국물이 밥 한 공기를 끝낸다고 봄. 겉절이 아삭이 진리라는 쪽 반박해봐.', '물김치는 국이 아님. 시원한 한 술이 간을 리셋함.', ARRAY['물김치','밥','맛'], 'A Korean man in his early 20s spooning watery kimchi broth over rice, summer table, candid'),
  ('맛식', '냉면 육수, 심심해야 맛임?', '난 냉면은 밍밍한 듯해야 면이 산다고 봄. 진한 육수파 나와봐.', '심심함은 실패가 아니라 온도임. 짜면 중간에 물을 찾게 됨.', ARRAY['냉면','육수','맛'], 'A Korean woman in her early 20s tasting cold noodle broth with chopsticks lifted, summer restaurant'),
  ('lifestyle', '일기, 아직도 쓸 가치 있음?', '난 세 줄 일기가 하루를 닫는다고 봄. 기록은 사진이면 된다는 사람 나와봐.', '일기는 문장이 아니라 마무리임. 안 쓰면 같은 하루가 반복처럼 남음.', ARRAY['일기','기록','습관'], 'A Korean woman in her early 20s writing three lines in a small notebook before bed, lamp light'),
  ('lifestyle', '이동은 팟캐스트가 맞음?', '난 출퇴근은 말이 있는 게 덜 지친다고 봄. 음악만 듣는다는 쪽 반박해봐.', '팟캐스트는 공부가 아니라 동행임. 한 편이 한 정거장을 짧게 함.', ARRAY['팟캐스트','출퇴근','취향'], 'A Korean man in his early 20s on a subway with earphones, calm, ordinary commute'),
  ('lifestyle', '주 1회 폰 내려놓기, 가능함?', '난 반나절만 내려놔도 주말이 길어진다고 봄. 연락이 끊긴다는 사람 논리 들어봄.', '디톡스는 자랑이 아니라 반나절임. 통째 하루는 불안만 키움.', ARRAY['디톡스','폰','주말'], 'A Korean woman in her early 20s leaving her phone in a drawer and picking up a book, Saturday afternoon'),
  ('lifestyle', '방 향초, 기분값 됨?', '난 불 하나 켜는 게 저녁을 바꾼다고 봄. 냄새 민감하다는 쪽 들어와.', '향초는 인테리어가 아니라 종료 의식임. 잠들기 전에 끄면 됨.', ARRAY['향초','저녁','방'], 'A Korean man in his early 20s lighting one small candle on a side table, evening apartment, no labels'),
  ('lifestyle', '짐 적은 방, 멘탈에 이득임?', '난 보이는 물건이 줄어야 집이 쉰다고 봄. 수납이 많아야 편하다는 사람 반박해봐.', '빈 바닥은 휑함이 아니라 동선임. 물건이 보이면 할 일이 보여서 쉼이 안 됨.', ARRAY['미니멀','방','멘탈'], 'A Korean woman in her early 20s sitting on a clear floor in a sparse room, one plant, relaxed'),
  ('lifestyle', '주말 아침 시장, 루틴으로 맞음?', '난 시장 한 바퀴가 주말 외출의 최소치라고 봄. 집 충전이 우선이라는 쪽 나와봐.', '시장은 장보기가 아니라 사람 소리임. 한 시간이면 주말이 시작됨.', ARRAY['시장','주말','루틴'], 'A Korean man in his early 20s walking a morning market with a small tote, looking at produce'),
  ('lifestyle', '보드게임, 술자리보다 남음?', '난 게임 한 판이 대화 주제를 만들어 준다고 봄. 술이 있어야 모임이라는 사람 들어와.', '보드는 승부가 아니라 자리임. 마시지 않아도 두 시간이 참.', ARRAY['보드게임','모임','취향'], 'Young Korean people in their early 20s around a low table with a board game, snacks, laughing candid'),
  ('lifestyle', '플래너 수기, 앱보다 맞음?', '난 손으로 적는 주간이 일정 체감이 크다고 봄. 알림이 플래너라는 쪽 논리 가져와.', '수기는 느린 게 아니라 한 번 더 봄. 앱은 미루기 버튼이 너무 가까움.', ARRAY['플래너','수기','일정'], 'A Korean woman in her early 20s writing a weekly plan in a paper planner, coffee beside it'),
  ('lifestyle', '산책, 운동 대신 됨?', '난 40분 걷기가 운동 출석보다 지속된다고 봄. 땀이 나야 운동이라는 사람 반박해봐.', '산책은 대충이 아니라 매일임. 기록 없는 걸음이 다음 주를 살림.', ARRAY['산책','운동','습관'], 'A Korean man in his early 20s walking a neighborhood sidewalk at dusk, ordinary jacket, no logos'),
  ('lifestyle', '계절 노래 목록, 필요한가?', '난 계절마다 목록을 바꾸는 게 기분을 구분한다고 봄. 셔플이면 된다는 쪽 나와봐.', '목록은 감성 과장이 아님. 같은 노래만 나오면 계절이 안 바뀜.', ARRAY['플레이리스트','계절','취향'], 'A Korean woman in her early 20s choosing songs on a phone by a window, autumn light, earphones in hand'),
  ('lifestyle', '중고 가구, 새 것보다 방 맛임?', '난 자국 있는 책상 하나가 방을 살린다고 봄. 새 가구여야 정돈이라는 사람 들어와.', '중고 가구는 낡음이 아니라 크기 맞춤임. 새 거 기다리다 바닥이 빔.', ARRAY['중고','가구','방'], 'A Korean man in his early 20s wiping a secondhand wooden desk in a small room, pleased'),
  ('lifestyle', '하루 한 장 사진, 기록이 됨?', '난 하루에 한 장만 찍는 게 나중에 본다고 봄. 많이 찍어야 남는다는 쪽 반박해봐.', '한 장은 제한이 아니라 선택임. 백 장은 앨범에서 안 열림.', ARRAY['사진','기록','하루'], 'A Korean woman in her early 20s taking one photo of her meal by a window, phone then set down'),
  ('lifestyle', '주말 일찍 자기, 회복임?', '난 토요일 열한 시 잠이 월요일을 살린다고 봄. 주말 밤이 본편이라는 사람 나와봐.', '일찍 자는 주말은 손해 봄이 아님. 일요일 낮이 진짜 휴식임.', ARRAY['수면','주말','회복'], 'A Korean man in his early 20s turning off a lamp and lying down on a weekend night, calm'),
  ('romance', '기념일 선물, 취향이 금액보다 큼?', '난 상대가 말한 작은 게 비싼 surprise보다 남다고 봄. 금액이 마음이라는 쪽 들어와.', '선물은 가격표가 아니라 기억임. 평소 한 마디가 포장보다 김.', ARRAY['선물','기념일','연애'], 'A Korean woman in her early 20s handing a small wrapped gift across a cafe table, partner smiling'),
  ('romance', '연락 없는 하루, 이 정도면 됨?', '난 바쁜 하루 침묵은 괜찮다고 봄. 매일 안부가 사랑이라는 사람 반박해봐.', '하루 비움은 식음이 아님. 다음 날 이유를 말하면 온도가 유지됨.', ARRAY['연락','하루','연애'], 'A Korean man in his early 20s finishing work and then opening a chat, tired but about to reply'),
  ('romance', '연애 상담, 친구에게 어디까지임?', '난 싸움 내용은 당사자끼리 두는 게 맞다고 봄. 친구 의견이 필요하다는 쪽 나와봐.', '상담은 감정까지만. 상대 험담이 되면 화해가 어려워짐.', ARRAY['상담','친구','연애'], 'A Korean woman in her early 20s talking with a friend at a cafe, serious but not dramatic, phones down'),
  ('romance', '전 애인 이야기, 해도 됨?', '난 물어보면 짧게 말하는 게 솔직이라고 봄. 과거는 닫아야 한다는 사람 논리 들어봄.', '과거는 자랑이 아님. 비교가 시작되면 그때 주제를 바꿈.', ARRAY['과거','솔직','연애'], 'A Korean man in his early 20s speaking calmly with a partner on a bench, no phones, daytime'),
  ('romance', '데이트 사진, 꼭 남겨야 함?', '난 한 장이면 충분하고 없어도 그날은 남다고 봄. 기록이 없으면 안 만난 거라는 쪽 반박해봐.', '사진은 증거가 아님. 찍느라 음식이 식으면 날짜만 남음.', ARRAY['사진','데이트','기록'], 'Two Korean people in their early 20s putting a phone away to eat, one photo already taken, casual table'),
  ('romance', '밥 취향 다르면, 데이트가 힘듦?', '난 번갈아 고르면 취향 차이가 재미라고 봄. 입맛이 같아야 오래간다는 사람 들어와.', '다른 메뉴는 양보 연습임. 매번 맞추기만 하면 한 사람이 지침.', ARRAY['밥','취향','데이트'], 'A Korean woman in her early 20s and a partner pointing at different dishes on one menu, smiling'),
  ('romance', '늦는 연락, 이유부터가 매너임?', '난 늦으면 이유 한 줄을 먼저 보내는 게 애정이라고 봄. 도착해서 말하면 된다는 쪽 나와봐.', '이유는 변명이 아니라 대기 시간임. 침묵이 제일 길게 느껴짐.', ARRAY['지각','연락','연애'], 'A Korean man in his early 20s sending a short late message on the street, apologetic, walking'),
  ('romance', '호감 티, 빨리 내는 게 맞음?', '난 좋은 티를 일찍 내는 게 서로 덜 헤맨다고 봄. 티 내면 가벼워 보인다는 사람 반박해봐.', '티는 들이댐이 아니라 방향임. 숨기면 상대는 다른 신호를 봄.', ARRAY['호감','티','썸'], 'A Korean woman in her early 20s laughing openly on a second meeting, cafe, candid warmth'),
  ('romance', '커플템, 있어야 티가 남?', '난 같은 물건 없이도 연애라고 봄. 맞춰야 공개라는 쪽 논리 가져와.', '커플템은 놀이임. 없어도 약속이 맞으면 밖에서도 보임.', ARRAY['커플템','공개','연애'], 'A Korean man in his early 20s walking with a partner in different outfits, easy pace, evening'),
  ('romance', '생일 서프라이즈, 부담임?', '난 미리 말한 식사가 깜짝 이벤트보다 따뜻하다고 봄. 서프라이즈파 나와봐.', '깜짝은 감동이 아니라 일정 습격일 수 있음. 좋아하는 방식부터 물음.', ARRAY['생일','서프라이즈','연애'], 'A Korean woman in her early 20s arriving at a reserved small table, partner already there, calm happy'),
  ('romance', '연애 중 혼자 여행, 돼도 됨?', '난 각자 여행 하루가 연애를 덜 지치게 한다고 봄. 같이 가야 신뢰라는 사람 반박해봐.', '혼자 여행은 거리가 아님. 일정만 공유하면 기다림이 안심이 됨.', ARRAY['혼자여행','신뢰','연애'], 'A Korean man in his early 20s with a day bag at a station, sending a departure text, content'),
  ('romance', '싸움, 다음 날 다시 꺼내는 게 맞음?', '난 잠든 뒤 한 번 더 정리하는 게 재발 방지라고 봄. 지난 얘기 끄집어내지 말자는 쪽 들어와.', '다음 날 얘기는 복수 아님. 감정 빠진 한 줄이 같은 싸움을 줄임.', ARRAY['싸움','대화','연애'], 'A Korean woman in her early 20s talking quietly with a partner the next morning, mugs on the table'),
  ('romance', '호감 거절, 바로 말하는 게 매너임?', '난 없는 마음은 그 자리에서 말하는 게 예의라고 봄. 시간을 주면 덜 아프다는 사람 나와봐.', '거절은 차가움이 아니라 일정 반환임. 애매한 하루가 제일 김.', ARRAY['거절','호감','매너'], 'A Korean man in his early 20s speaking kindly and directly across a quiet table, daytime, serious gentle face');
